function chave(v) {
  return String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toUpperCase()
    .replace(/\s+/g, ' ');
}

function excelDate(v) {
  if (v === null || v === undefined || v === '') return '';

  const n = Number(v);

  if (!Number.isFinite(n)) {
    return String(v);
  }

  const base = Date.UTC(1899, 11, 30);
  const data = new Date(base + n * 86400000);

  return data.toISOString().slice(0, 10);
}

return items.map(item => {
  const j = item.json;

  const chaveImportacao = [
    'NEOENERGIA_REDE',
    chave(j['Codigo_SAP_EKT']),
    chave(j['Codigo_SAP_NE']),
    chave(j['Codigo_SAP_NDB']),
    chave(j['Descricao_Sucinta']),
    chave(j['Espec_Tecnica']),
    chave(j['Refer_Fornecedor']),
    chave(j['Fornec_razao_social'])
  ].join('|');

  return {
    json: {
      Title: j['Descricao_Sucinta'] ?? '',

      Codigo_Nordeste: String(j['Codigo_SAP_NE'] ?? ''),
      Codigo_Elektro: String(j['Codigo_SAP_EKT'] ?? ''),
      Codigo_Brasilia: String(j['Codigo_SAP_NDB'] ?? ''),

      Familia: j['Familia'] ?? '',
      SubFamilia: '',

      Descricao: j['Descricao_Sucinta'] ?? '',
      Descricao_Completa: j['Descricao_Completa'] ?? '',

      Especificacao_Tecnica: j['Espec_Tecnica'] ?? '',
      Refer_Fornecedor: j['Refer_Fornecedor'] ?? '',
      Desenho_Fornecedor: j['Desenho_Fornecedor'] ?? '',

      Fornecedor: j['Fornec_razao_social'] ?? '',
      CNPJ: String(j['CNPJ'] ?? ''),

      Data_Homologacao: excelDate(j['Data_homologacao']),
      Data_Vencimento_Homologacao: excelDate(j['Data_venc_homolog']),

      Ref_Documentacao: j['Ref_Documentacao'] ?? '',
      Modo_Fornecimento: j['Modo_fornec'] ?? '',
      CA: j['CA'] ?? '',
      Observacao: j['Observacao'] ?? '',

      Tipo_Gestao_Recebimento:
        j['Tipo de Gestão de Recebimento'] ?? '',

      Status_Homologacao: '',
      Nome_Normalizado: '',

      Fonte: 'NEOENERGIA_REDE',

      Numero_Patrimonio_Nordeste: '',
      Numero_Patrimonio_Elektro: '',
      Numero_Patrimonio_Brasilia: '',

      Chave_Importacao: chaveImportacao
    }
  };
});

